import React, { useContext } from 'react';
import { AuthContext } from './AuthContext';
import Products from './Products';

function MainPage() {
  const { auth } = useContext(AuthContext);
  const username = auth.user ? auth.user : "Guest";

  const mainPageStyle = {
    position: 'relative',
    background: 'linear-gradient(135deg, #000, #333)', // Ana renk gradyanı
    minHeight: '100vh',
    color: '#fff',
    padding: '20px',
    overflow: 'hidden'
  };

  const backgroundStyle = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    background: 'url(/images/rock-bg.jpg) no-repeat center center',
    backgroundSize: 'cover',
    opacity: 0.5,
    zIndex: -1
  };

  return (
    <div style={mainPageStyle}>
      {/* Arka plan resmi */}
      <div style={backgroundStyle}></div>

      {/* Başlık Bölümü */}
      <header style={{ textAlign: 'center', marginBottom: '40px', textShadow: '2px 2px 4px #000' }}>
        <h1 style={{ fontFamily: 'Anton, sans-serif', fontSize: '3.5rem', marginBottom: '0.5em' }}>
          Rock Your World!
        </h1>
        <p style={{ fontSize: '1.5rem', marginBottom: '1em' }}>
          Welcome, {username}! Explore our killer collection of guitars, effects, and more.
        </p>
      </header>

      {/* Ürünler Bölümü (Yarı saydam kutu ile öne çıkarılmış) */}
      <section style={{ 
          backgroundColor: 'rgba(0, 0, 0, 0.7)', 
          padding: '20px', 
          borderRadius: '8px', 
          position: 'relative'
        }}>
        <Products />
      </section>
    </div>
  );
}

export default MainPage;
